"OLAYLAR_KI117:1699-09-22:0":{"b": ["تسلیم کامانیچه به لهستان", "05950f7a"], "d": ["بنا بر پیمان کارلوویتس 26 ژانویه 1699، تخلیهٔ پودولیا در سپتامبر کامل شد؛ کلیدهای کامانیچه در 22 سپتامبر 1699 به کمیسیون لهستانی تسلیم شد. انتقال سنجاق به لهستان، همراه با دژهای وابسته (بار، مجیبوژ، یازلوفچه)، عملاً در همین روز انجام شد.", "15c85c1d"]},
"OLAYLAR_KRONOEKSIK0921:1603-06-07:0":{"b": ["خفه کردن شاهزاده محمود", "9fc2fdb5"], "d": ["محمد سوم که به پسر بزرگش شاهزاده محمود مظنون بود که چشم به تاج و تخت دوخته و می‌تواند او را از تخت پایین کشد، او را خفه کرد؛ مادر شاهزاده و حدود سی خدمتکار او به دریا انداخته شدند. در میانهٔ شورش‌های جلالی و ناآرامی آناتولی، پادشاه دیده بود که سپاه به شاهزاده گرایش دارد؛ ثبت شده که والده سلطان نیز از مادر شاهزاده ناخشنود بود. این اعدام یکی از حلقه‌های پایانی راهی است که شش ماه بعد با مرگ محمد سوم به آن انجامید که تنها احمد یکم سیزده‌ساله بر تخت بماند و سنت برادرکشی عملاً پایان یابد.", "bacf93cd"]},
"OLAYLAR_KRONOEKSIK0921:1621-01-01:0":{"b": ["زمستان بی‌سابقه — یخ بستن تنگهٔ استانبول", "9e4fb488"], "d": ["در حالی که تدارک لشکرکشی لهستان ادامه داشت، استانبول زمستانی بی‌سابقه را گذراند: تنگه یخ بست و در شهر خوردنی و نوشیدنی یافت نمی‌شد. صدراعظم گوزلجه علی پاشا که به‌خاطر تنگنای بازار نگران جان خود بود، اندکی پس از آنکه هوا بهتر شد و وضع به حال عادی برگشت، در 15 ربیع‌الآخر (9 مارس) درگذشت و اوهریلی حسین پاشا جای او را گرفت. اوتاق در 7 جمادی‌الآخر (29 آوریل) در صحرای داود پاشا برپا شد؛ لشکرکشی‌ای که عثمان دوم را به خوتین خواهد برد، پس از این زمستان آغاز شد.", "146293da"]},
"OLAYLAR_KRONOEKSIK0921:1826-04-08:0":{"b": ["پایان ساخت مسجد نصرتیه", "30dfdc64"], "d": ["ساخت مسجد سلطانی که محمود دوم در توپخانه ساخته بود، در 8 آوریل 1826 به پایان رسید؛ بنا جای مسجد قشلهٔ توپخانه را گرفت که در آتش‌سوزی بزرگ 24 فوریه 1823 خاکستر شده بود و ساختش در ژوئن 1823 آغاز شده بود. معمار آن کریکور امیرا کالفا از خاندان بالیان است؛ از پرجلوه‌ترین نمونه‌های سبک امپایر در معماری مساجد عثمانی شمرده می‌شود. در 14 مه 1826 مناره‌ها تا شرفهٔ پایین ویران و بلندتر بازسازی شد؛ نام «نصرتیه» (پیروزی) مسجد در ژوئن همان سال به یاد برچیده شدن ادارهٔ ینی‌چری داده شده است و در میان مردم مسجد توپخانه نامیده می‌شود.", "3043db31"]},
"OLAYLAR_KRONOEKSIK0921:1883-11-03:0":{"b": ["تأسیس مکتب هندسهٔ ملکیه", "abfa076e"], "d": ["پس از جنگ عثمانی-روس 1877-78، به‌منظور پرورش مهندس از میان ترک‌ها و مسلمانان، مکتب هندسهٔ ملکیه در 3 نوامبر 1883 به دست عبدالحمید دوم تأسیس شد. مکتب آموزش مهندسی غیرنظامی را در کنار مهندس‌خانه‌های نظامی به‌عنوان نهادی جداگانه نهادینه کرد؛ مراسم گشایش ساختمان خود آن در 29 اکتبر 1884 برگزار شد. در 1909 از اداره نظامی گرفته و به نظارت نافعه وابسته شد و نام مدرسهٔ عالی مهندسی را گرفت.", "48cf01ce"]},
"OLAYLAR_KUNFUZE_1016:1814-03-01:0":{"b": ["نیروهای محمدعلی قنفذه را از وهابیان گرفتند", "fbeec58b"], "d": ["لشکرکشی دریایی که از جده برخاست، قنفذه را که پنج سال در دست شیخ عسیر، تامی، بود، بی‌خون‌ریزی گرفت.", "fa0c98f2"]},
