"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0998-03-03:0":{"b": ["محمود برادرش اسماعیل را شکست داد و بر تخت غزنوی نشست", "b2acf57c"], "d": ["محمود که در نیشابور بود، وصیت پدرش را نپذیرفت و دست به کار شد؛ در ربیع‌الاول 388 (مارس 998) سپاه دو برادر رو در رو شد و محمود اسماعیل را شکست داد و بر تخت غزنوی نشست.", "3c2c1e3d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0999-10-14:0":{"b": ["ایلک‌خان نصر قراخانی به بخارا درآمد؛ خاندان سامانی به اوزکند تبعید شد، دولت عملاً پایان یافت", "ec519748"], "d": ["در ذوالقعده 389 (اکتبر 999) قراخانیان بخارا را اشغال کردند؛ عبدالملک اسیر شد و خاندان سامانی به اوزکند برده و زندانی شد. ایلک‌خان نصر والیان خود را در ناحیه گماشت.", "ef9a0a65"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:0":{"b": ["دوج پیترو دوم اورسئولو شهرهای دالماسیا را به زیر یوغ گرفت و «دوک دالماسیا» شد", "fa3dde09"], "d": ["اورسئولو که به دعوت دالماسیایی‌ها با ناوگانی بزرگ به راه افتاد، کروات‌ها و ناراتان‌ها را شکست داد، آدریاتیک را از دزدی دریایی پاک کرد و از شهرهای دالماسیا مالیات و سوگند وفاداری گرفت؛ عنوان «دوک دالماسیا» را گرفت. زارا در 1000 با دوج بیعت کرد.", "d2c778fc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:1":{"b": ["راگوزا (دوبروونیک) و شهرهای جنوب دالماسیا با اورسئولو بیعت کردند", "6121e2e9"], "d": ["در لشکرکشی اورسئولو به دالماسیا، راگوزا، به‌عنوان جنوبی‌ترین شهر دالماسیا، با سفیران و اسقف اعظم خود در جزیرهٔ کوچک سان ماسیمو از سپاه دوج استقبال کرد و وفاداری خود را به ونیز پیشکش نمود.", "638f8cad"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1013-01-01:0":{"b": ["محمود لاهور را از هندوشاهیان گرفت؛ لاهور محبوب‌ترین شهر غزنویان شد", "37ab3445"], "d": ["لاهور که پس از 991 در دست هندوشاهیان بود، در 1013-1014 به دست محمود غزنوی افتاد؛ محمود دژ لاهور را استوار کرد و پادگانی از سربازان ترک و تاجیک که از خراسان آورده بود، برپا ساخت. چون غزنویان استقلال خود را از دست دادند (پس از 1157)، لاهور مرکز بخشی شد که در خاور حیات خود را نگه داشت.", "90b6f385"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1015-01-01:0":{"b": ["پادشاه روبر دوم پس از جنگی سیزده‌ساله دوکنشین بورگونی را به تاج فرانسه می‌پیوندد", "257ea2c6"], "d": ["پس از مرگ دوک هانری در 1002، بر سر دوکنشین بورگونی جنگ درگرفت؛ روبر دوم، پادشاه فرانسه، با وجود ایستادگی اتو-ویلیام، کنت بورگونی، در پایان جنگی سیزده‌ساله در 1015 دوکنشین را به پادشاهی پیوست و به پسرش هانری (بعدها هانری یکم) داد.", "9b353b9c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:0":{"b": ["باسیلیوس دوم به اوهرید درآمد: پایتخت بلغار باختری به دست بیزانس افتاد", "05fe0972"], "d": ["سلسلهٔ بلغار که پس از مرگ سامیوئل چهار سال ایستادگی کرده بود، در آغاز 1018 در دروازه‌های اوهرید به باسیلیوس دوم تسلیم شد. اما اسقف‌نشین اعظم اوهرید زیر فرمان بیزانس همچنان مرکز مسیحیت اسلاوی ماند.", "b6ac5adb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:1":{"b": ["بولسلاو شجاع، پادشاه لهستان، با پشتیبانی آلمانی و پچنگ کیف را گرفت", "3e44ca65"], "d": ["در اوت 1018 بولسلاو با نیروهای آلمانی و پچنگ کیف را گرفت؛ بولسلاو که یاروسلاو را در رود بوگ شکست داده بود، داماد خود سویاتوپولک را بر تخت نشاند. یاروسلاو تنها در 1019 توانست کیف را بازپس گیرد.", "33889946"]},
